t.script:
let observer;
window.addEventListener('load', function () {
    console.log("===== Observer paymentButton");

    const paymentButton = document.querySelector(
        'button[name="o_payment_submit_button"]'
    );
    if (!paymentButton) return;

    // Force initial state
    paymentButton.disabled = true;

    observer = new MutationObserver(() => {
        if (!paymentButton.disabled) {
            console.log("===== Re-disabling paymentButton");
            paymentButton.disabled = true;
        }
    });

    observer.observe(paymentButton, {
        attributes: true,
        attributeFilter: ['disabled']
    });
});

console.log("Loading Web Security");

let verify_email_action = "verify_email";
let paymentButton = document.querySelector('button[name="o_payment_submit_button"]');
let intervalDelay = 5000;
let intervalId = null;

function verifyEmail() {
    console.log('verifyEmail');

    const formElement = document.getElementById('o_payment_form');
    const verify_email_txt = document.getElementById('verify_email_txt');
    const transactionRoute = formElement.getAttribute('data-transaction-route');
    const url = window.location.origin + transactionRoute;

    const accessToken = formElement.getAttribute('data-access-token');
    const csrf_token = odoo.csrf_token;

    let data = {
      "id": 4,
      "jsonrpc": "2.0",
      "method": "call",
      "params": {
        "verify_email_action":verify_email_action,
        "access_token": accessToken,
        "csrf_token": csrf_token
      }
    };

    fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(data)
    })
    .then(response => response.json())
    .then(result => {

      if (result && result.result && result.result.error) {
        console.error('Error from server:', result.result.error);
      } else {

        intervalDelay = result.result.email_verification_delay * 1000;

        if (intervalId !== null) {
            console.log("Updating interval ID:", intervalId);
            clearInterval(intervalId);
            intervalId = setInterval(verifyEmail, intervalDelay); 
        }

        if (document.getElementById('verify_email_txt') ) {
            if (intervalId !== null) {
                console.log("interval ID:", intervalId);
            } else {
                intervalId = setInterval(verifyEmail, intervalDelay); 
            }
            if (result.result.email_verified == true){
                console.log("email_verified");
                clearInterval(intervalId);

                let paymentButton = document.querySelector('button[name="o_payment_submit_button"]');

                if (paymentButton && observer){
                    disableObserver();
                    disable_payment_button(false);

                }
                disable_payment_button(false);
            } else if (result.result.verify_email_action == 'refresh'){
                console.log("Refresh");

                disable_payment_button(true);

            } else {
                console.log("==> Error no action found");
            }

            verify_email_txt.textContent = result.result.message;

            verify_email_action = result.result.verify_email_action
        } 
      }
    })
    .catch(error => {
      console.error('Error:', error);
    });



}

function disable_payment_button(disabled){
    const paymentButton = document.querySelector(
        'button[name="o_payment_submit_button"]'
    );
    if (paymentButton){
        console.log("\tdisable_payment_button:", disabled);
        paymentButton.disabled = disabled;
    }
}

function disableObserver() {
    observer.disconnect();
    console.log("Observer has been disabled");
}
